-- 5. Repair proposals (HU-25). Each one is created pending and then voted or
--    decided, so the triggers of migration 010 apply the outcome.
-- #VIG-S015: pending
UPDATE incident_resolution SET proposed_at = now() - interval '30 hours' WHERE id_resolution = (SELECT id_resolution FROM incident_resolution WHERE id_incident = (SELECT id_incident FROM road_incident WHERE tracking_code = '#VIG-S015') AND status = 'PENDING');
-- #VIG-S027: pending
UPDATE incident_resolution SET proposed_at = now() - interval '10 hours' WHERE id_resolution = (SELECT id_resolution FROM incident_resolution WHERE id_incident = (SELECT id_incident FROM road_incident WHERE tracking_code = '#VIG-S027') AND status = 'PENDING');
-- #VIG-S003: community
UPDATE incident_resolution SET proposed_at = now() - interval '120 hours' WHERE id_resolution = (SELECT id_resolution FROM incident_resolution WHERE id_incident = (SELECT id_incident FROM road_incident WHERE tracking_code = '#VIG-S003') AND status = 'PENDING');
-- #VIG-S009: community
UPDATE incident_resolution SET proposed_at = now() - interval '90 hours' WHERE id_resolution = (SELECT id_resolution FROM incident_resolution WHERE id_incident = (SELECT id_incident FROM road_incident WHERE tracking_code = '#VIG-S009') AND status = 'PENDING');
-- #VIG-S013: author
UPDATE incident_resolution SET proposed_at = now() - interval '60 hours' WHERE id_resolution = (SELECT id_resolution FROM incident_resolution WHERE id_incident = (SELECT id_incident FROM road_incident WHERE tracking_code = '#VIG-S013') AND status = 'PENDING');
UPDATE incident_resolution SET status = 'APPROVED_BY_AUTHOR', id_approver_user = '283be0dd-d44f-42a4-8354-e5064d3c4ed6'::uuid, resolved_at = now() WHERE id_resolution = (SELECT id_resolution FROM incident_resolution WHERE id_incident = (SELECT id_incident FROM road_incident WHERE tracking_code = '#VIG-S013') AND status = 'PENDING');
-- #VIG-S020: rejected
UPDATE incident_resolution SET proposed_at = now() - interval '70 hours' WHERE id_resolution = (SELECT id_resolution FROM incident_resolution WHERE id_incident = (SELECT id_incident FROM road_incident WHERE tracking_code = '#VIG-S020') AND status = 'PENDING');

COMMIT;

-- Check: one row per demo report with its status, photos, votes and comments.
SELECT tracking_code, city, current_status,
       (SELECT count(*) FROM incident_photo p WHERE p.id_incident = i.id_incident) AS photos,
       (SELECT count(*) FROM incident_upvote u WHERE u.id_incident = i.id_incident) AS upvotes,
       (SELECT count(*) FROM incident_comment c WHERE c.id_incident = i.id_incident) AS comments
  FROM road_incident i WHERE tracking_code LIKE '#VIG-S%' ORDER BY tracking_code;
